package api

import (
	"encoding/json"
	"net/http"

	"giftshop/internal/service"
)

// Handlers own HTTP concerns only: parsing requests, calling service
// methods, writing responses (D1). Business rules live in service (D4).
type Handlers struct {
	shop *service.Shop
}

func New(shop *service.Shop) *Handlers { return &Handlers{shop: shop} }

func (h *Handlers) Register(mux *http.ServeMux) {
	mux.HandleFunc("POST /users", h.createUser)
	mux.HandleFunc("POST /credit", h.credit)
	mux.HandleFunc("POST /gift", h.gift)
}

type createUserReq struct {
	Email string `json:"email"`
}

func (h *Handlers) createUser(w http.ResponseWriter, r *http.Request) {
	var req createUserReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, "bad json")
		return
	}
	u, err := h.shop.RegisterUser(req.Email)
	if err != nil {
		writeErr(w, http.StatusBadRequest, err.Error())
		return
	}
	writeJSON(w, http.StatusCreated, u)
}

type creditReq struct {
	UserID string `json:"user_id"`
	Cents  int    `json:"cents"`
}

func (h *Handlers) credit(w http.ResponseWriter, r *http.Request) {
	var req creditReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, "bad json")
		return
	}
	if err := h.shop.CreditCents(req.UserID, req.Cents); err != nil {
		writeErr(w, http.StatusBadRequest, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

type giftRecipientReq struct {
	Email   string  `json:"email"`
	Dollars float64 `json:"dollars"`
}

type giftReq struct {
	Recipients []giftRecipientReq `json:"recipients"`
}

// giftResult is the HTTP view of service.GiftOutcome: the typed error
// becomes a message, everything else is plain JSON.
type giftResult struct {
	Email string `json:"email"`
	OK    bool   `json:"ok"`
	Cents int    `json:"cents,omitempty"`
	Error string `json:"error,omitempty"`
}

type giftResp struct {
	Credited int          `json:"credited"`
	Failed   int          `json:"failed"`
	Results  []giftResult `json:"results"`
}

func (h *Handlers) gift(w http.ResponseWriter, r *http.Request) {
	var req giftReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, "bad json")
		return
	}
	if len(req.Recipients) == 0 {
		writeErr(w, http.StatusBadRequest, "no recipients")
		return
	}
	gifts := make([]service.Gift, len(req.Recipients))
	for i, rc := range req.Recipients {
		gifts[i] = service.Gift{Email: rc.Email, Dollars: rc.Dollars}
	}
	resp := giftResp{Results: make([]giftResult, 0, len(gifts))}
	for _, o := range h.shop.GiftBatch(gifts) {
		res := giftResult{Email: o.Email}
		if o.Err != nil {
			res.Error = o.Err.Error()
			resp.Failed++
		} else {
			res.OK = true
			res.Cents = o.Cents
			resp.Credited++
		}
		resp.Results = append(resp.Results, res)
	}
	writeJSON(w, http.StatusOK, resp)
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func writeErr(w http.ResponseWriter, code int, msg string) {
	writeJSON(w, code, map[string]string{"error": msg})
}

