	Email   string  `json:"email"`
	Dollars float64 `json:"dollars"`
}

type giftReq struct {
	Recipients []giftRecipientReq `json:"recipients"`
}

type giftResultResp struct {
	Email  string `json:"email"`
	Status string `json:"status"`
	Cents  int    `json:"cents,omitempty"`
	Error  string `json:"error,omitempty"`
}

// gift delegates the whole batch to shop.Gift; per-recipient statuses
// are classified in service, so this handler never inspects store
// errors (D1). Unknown emails come back as ordinary results (D3).
func (h *Handlers) gift(w http.ResponseWriter, r *http.Request) {
	var req giftReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, "bad json")
		return
	}
	recipients := make([]service.GiftRecipient, len(req.Recipients))
	for i, rc := range req.Recipients {
		recipients[i] = service.GiftRecipient{Email: rc.Email, Dollars: rc.Dollars}
	}
	outcomes := h.shop.Gift(recipients)
	results := make([]giftResultResp, len(outcomes))
	for i, o := range outcomes {
		res := giftResultResp{Email: o.Email, Status: o.Status, Cents: o.Cents}
		if o.Err != nil {
			res.Error = o.Err.Error()
		}
		results[i] = res
	}
	writeJSON(w, http.StatusOK, map[string]any{"results": results})
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func writeErr(w http.ResponseWriter, code int, msg string) {
	writeJSON(w, code, map[string]string{"error": msg})
}

