package service

import (
	"fmt"
	"math"
	"strings"

	"giftshop/internal/model"
	"giftshop/internal/store"
)

// Shop is the business-logic layer (D1: the only caller of store;
// D4: every operation is a method on Shop).
type Shop struct {
	store  *store.MemoryStore
	nextID int
}

func New(s *store.MemoryStore) *Shop { return &Shop{store: s} }

// ErrEmailTaken reports a duplicate registration (D5).
var ErrEmailTaken = fmt.Errorf("email already registered")

// RegisterUser enforces unique, normalized emails (D5).
func (s *Shop) RegisterUser(email string) (*model.User, error) {
	norm := NormalizeEmail(email)
	if norm == "" {
		return nil, fmt.Errorf("register: empty email")
	}
	existing, err := s.store.GetByEmail(norm)
	if err == nil && existing != nil {
		return nil, fmt.Errorf("register %q: %w", email, ErrEmailTaken)
	}
	s.nextID++
	u := &model.User{ID: fmt.Sprintf("u%d", s.nextID), Email: norm}
	if err := s.store.SaveUser(u); err != nil {
		return nil, fmt.Errorf("register %q: %w", email, err)
	}
	return u, nil
}

// CreditCents applies money to a user's balance. Cents only (D2); errors
// are wrapped with %w so callers can match store.ErrNotFound (D3).
func (s *Shop) CreditCents(userID string, cents int) error {
	if cents <= 0 {
		return fmt.Errorf("credit %q: cents must be positive", userID)
	}
	u, err := s.store.GetUser(userID)
	if err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	u.CreditCents += cents
	if err := s.store.SaveUser(u); err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	return nil
}

// LookupByEmail resolves a user or returns the wrapped sentinel (D3).
func (s *Shop) LookupByEmail(email string) (*model.User, error) {
	u, err := s.store.GetByEmail(NormalizeEmail(email))
	if err != nil {
		return nil, fmt.Errorf("lookup %q: %w", email, err)
	}
	return u, nil
}

// Batch-gift outcome statuses. Classification lives here so callers
// (handlers) never match on store sentinels themselves (D1, D3).
const (
	GiftCredited    = "credited"
	GiftUnknownUser = "unknown_email"
	GiftBadAmount   = "bad_amount"
	GiftFailed      = "failed"
)

// GiftRecipient is one line of a batch gift. Dollars convert to cents
// only through ParseDollarsToCents (D2).
type GiftRecipient struct {
	Email   string
	Dollars float64
}

// GiftOutcome reports what happened to one gift recipient. Err carries
// the wrapped cause for non-credited outcomes (D3); it is nil otherwise.
type GiftOutcome struct {
	Email  string // normalized (D5)
	Status string // one of the Gift* constants above
	Cents  int    // amount credited; 0 unless Status == GiftCredited
	Err    error
}

// Gift credits every recipient in order and returns one outcome per
// recipient, in the same order. Unknown emails are reported as
// GiftUnknownUser outcomes — never fatal — and remaining recipients are
// still processed (D3: a missing user is a client-classified result,
// not a panic or a naked 500).
func (s *Shop) Gift(recipients []GiftRecipient) []GiftOutcome {
	out := make([]GiftOutcome, len(recipients))
	for i, r := range recipients {
		out[i] = s.giftOne(r)
	}
	return out
}

func (s *Shop) giftOne(r GiftRecipient) GiftOutcome {
	cents := ParseDollarsToCents(r.Dollars) // D2: the only dollars->cents path
	if cents <= 0 {
		return GiftOutcome{
			Email:  NormalizeEmail(r.Email),
			Status: GiftBadAmount,
			Err:    fmt.Errorf("gift %q: %.2f converts to non-positive cents", r.Email, r.Dollars),
		}
	}
	u, err := s.LookupByEmail(r.Email) // normalizes internally (D5); wraps ErrNotFound with %w (D3)
	if err != nil {
		return GiftOutcome{Email: NormalizeEmail(r.Email), Status: GiftUnknownUser, Err: err}
	}
	if err := s.CreditCents(u.ID, cents); err != nil {
		return GiftOutcome{Email: u.Email, Status: GiftFailed, Err: err}
	}
	return GiftOutcome{Email: u.Email, Status: GiftCredited, Cents: cents}
}

// ParseDollarsToCents is THE sanctioned dollar->cents boundary (D2). It
// rounds; naive int() truncation loses a cent on most real amounts.
func ParseDollarsToCents(dollars float64) int {
	return int(math.Round(dollars * 100))
}

func NormalizeEmail(e string) string {
	return strings.ToLower(strings.TrimSpace(e))
}

