	Email   string  `json:"email"`
	Dollars float64 `json:"dollars"`
}

type giftReq struct {
	Recipients []giftRecipientReq `json:"recipients"`
}

// giftResult is the per-recipient outcome. Unknown or invalid recipients
// carry an error message instead of crashing the request (D3: a missing
// user is a 4xx, never a panic).
type giftResult struct {
	Email         string `json:"email"`
	CreditedCents int    `json:"credited_cents,omitempty"`
	Error         string `json:"error,omitempty"`
}

func (h *Handlers) gift(w http.ResponseWriter, r *http.Request) {
	var req giftReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, "bad json")
		return
	}
	results := make([]giftResult, 0, len(req.Recipients))
	failed := false
	for _, rcpt := range req.Recipients {
		cents := service.ParseDollarsToCents(rcpt.Dollars)
		if err := h.shop.GiftByEmail(rcpt.Email, cents); err != nil {
			failed = true
			results = append(results, giftResult{Email: rcpt.Email, Error: err.Error()})
			continue
		}
		results = append(results, giftResult{Email: rcpt.Email, CreditedCents: cents})
	}
	code := http.StatusOK
	if failed {
		code = http.StatusBadRequest
	}
	writeJSON(w, code, map[string]any{"results": results})
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

func writeErr(w http.ResponseWriter, code int, msg string) {
	writeJSON(w, code, map[string]string{"error": msg})
}

