package service

import (
	"fmt"
	"math"
	"strings"

	"giftshop/internal/model"
	"giftshop/internal/store"
)

// Shop is the business-logic layer (D1: the only caller of store;
// D4: every operation is a method on Shop).
type Shop struct {
	store  *store.MemoryStore
	nextID int
}

func New(s *store.MemoryStore) *Shop { return &Shop{store: s} }

// ErrEmailTaken reports a duplicate registration (D5).
var ErrEmailTaken = fmt.Errorf("email already registered")

// RegisterUser enforces unique, normalized emails (D5).
func (s *Shop) RegisterUser(email string) (*model.User, error) {
	norm := NormalizeEmail(email)
	if norm == "" {
		return nil, fmt.Errorf("register: empty email")
	}
	existing, err := s.store.GetByEmail(norm)
	if err == nil && existing != nil {
		return nil, fmt.Errorf("register %q: %w", email, ErrEmailTaken)
	}
	s.nextID++
	u := &model.User{ID: fmt.Sprintf("u%d", s.nextID), Email: norm}
	if err := s.store.SaveUser(u); err != nil {
		return nil, fmt.Errorf("register %q: %w", email, err)
	}
	return u, nil
}

// CreditCents applies money to a user's balance. Cents only (D2); errors
// are wrapped with %w so callers can match store.ErrNotFound (D3).
func (s *Shop) CreditCents(userID string, cents int) error {
	if cents <= 0 {
		return fmt.Errorf("credit %q: cents must be positive", userID)
	}
	u, err := s.store.GetUser(userID)
	if err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	u.CreditCents += cents
	if err := s.store.SaveUser(u); err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	return nil
}

// GiftRecipient is one entry of a batch gift. Dollars come from the
// outside world and convert only via ParseDollarsToCents (D2).
type GiftRecipient struct {
	Email   string  `json:"email"`
	Dollars float64 `json:"dollars"`
}

// GiftOutcome reports the exact amount credited to one recipient.
type GiftOutcome struct {
	Email string
	Cents int
}

// GiftBatch credits every recipient by their dollar amount, rounded to
// cents (D2). All recipients are resolved before any money moves: an
// unknown email or non-positive amount aborts the batch with a wrapped
// store.ErrNotFound chain (D3) that handlers translate to a 4xx — it
// never panics or 500s.
func (s *Shop) GiftBatch(recipients []GiftRecipient) ([]GiftOutcome, error) {
	type target struct {
		id    string
		email string
		cents int
	}
	targets := make([]target, len(recipients))
	for i, r := range recipients {
		email := NormalizeEmail(r.Email)
		if email == "" {
			return nil, fmt.Errorf("gift: recipient %d has empty email", i)
		}
		cents := ParseDollarsToCents(r.Dollars)
		if cents <= 0 {
			return nil, fmt.Errorf("gift %q: dollars must be positive", email)
		}
		u, err := s.LookupByEmail(email)
		if err != nil {
			return nil, fmt.Errorf("gift %q: %w", email, err)
		}
		targets[i] = target{id: u.ID, email: email, cents: cents}
	}
	outcomes := make([]GiftOutcome, len(targets))
	for i, t := range targets {
		if err := s.CreditCents(t.id, t.cents); err != nil {
			return nil, fmt.Errorf("gift %q: %w", t.email, err)
		}
		outcomes[i] = GiftOutcome{Email: t.email, Cents: t.cents}
	}
	return outcomes, nil
}

// LookupByEmail resolves a user or returns the wrapped sentinel (D3).
func (s *Shop) LookupByEmail(email string) (*model.User, error) {
