var ErrEmailTaken = fmt.Errorf("email already registered")

// RegisterUser enforces unique, normalized emails (D5).
func (s *Shop) RegisterUser(email string) (*model.User, error) {
	norm := NormalizeEmail(email)
	if norm == "" {
		return nil, fmt.Errorf("register: empty email")
	}
	existing, err := s.store.GetByEmail(norm)
	if err == nil && existing != nil {
		return nil, fmt.Errorf("register %q: %w", email, ErrEmailTaken)
	}
	s.nextID++
	u := &model.User{ID: fmt.Sprintf("u%d", s.nextID), Email: norm}
	if err := s.store.SaveUser(u); err != nil {
		return nil, fmt.Errorf("register %q: %w", email, err)
	}
	return u, nil
}

// CreditCents applies money to a user's balance. Cents only (D2); errors
// are wrapped with %w so callers can match store.ErrNotFound (D3).
func (s *Shop) CreditCents(userID string, cents int) error {
	if cents <= 0 {
		return fmt.Errorf("credit %q: cents must be positive", userID)
	}
	u, err := s.store.GetUser(userID)
	if err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	u.CreditCents += cents
	if err := s.store.SaveUser(u); err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	return nil
}

// LookupByEmail resolves a user or returns the wrapped sentinel (D3).
func (s *Shop) LookupByEmail(email string) (*model.User, error) {
	u, err := s.store.GetByEmail(NormalizeEmail(email))
	if err != nil {
		return nil, fmt.Errorf("lookup %q: %w", email, err)
	}
	return u, nil
}

// Recipient is one gift target as stated by the outside world (GIFT-101).
type Recipient struct {
	Email   string
	Dollars float64
}

// Receipt reports what a gift credited to one recipient (D2: cents).
type Receipt struct {
	Email string `json:"email"`
	Cents int    `json:"cents"`
}

// Gift credits every recipient with their dollar amount (D4). Emails are
// normalized (D5) and dollars convert only through ParseDollarsToCents
// (D2); unknown recipients surface as wrapped store.ErrNotFound (D3), so
// callers translate them — the server never panics. Nothing is credited
// unless all recipients resolve.
func (s *Shop) Gift(recipients []Recipient) ([]Receipt, error) {
	if len(recipients) == 0 {
		return nil, fmt.Errorf("gift: no recipients")
	}
	totals := map[string]int{}
	for _, r := range recipients {
		norm := NormalizeEmail(r.Email)
		if norm == "" {
			return nil, fmt.Errorf("gift: empty email")
		}
		cents := ParseDollarsToCents(r.Dollars)
		if cents <= 0 {
			return nil, fmt.Errorf("gift %q: dollars must be positive", norm)
		}
		totals[norm] += cents
	}
	emails := make([]string, 0, len(totals))
	for email := range totals {
		emails = append(emails, email)
	}
	sort.Strings(emails)
	targets := make([]struct {
		userID string
		email  string
		cents  int
	}, 0, len(emails))
	for _, email := range emails {
		u, err := s.store.GetByEmail(email)
		if err != nil {
			return nil, fmt.Errorf("gift %q: %w", email, err)
		}
		targets = append(targets, struct {
			userID string
			email  string
			cents  int
		}{u.ID, email, totals[email]})
	}
	receipts := make([]Receipt, 0, len(targets))
	for _, t := range targets {
		if err := s.CreditCents(t.userID, t.cents); err != nil {
			return nil, fmt.Errorf("gift %q: %w", t.email, err)
		}
		receipts = append(receipts, Receipt{Email: t.email, Cents: t.cents})
	}
	return receipts, nil
}

// ParseDollarsToCents is THE sanctioned dollar->cents boundary (D2). It
// rounds; naive int() truncation loses a cent on most real amounts.
func ParseDollarsToCents(dollars float64) int {
	return int(math.Round(dollars * 100))
}

func NormalizeEmail(e string) string {
	return strings.ToLower(strings.TrimSpace(e))
}

