// gift implements GIFT-101: batch credit by email. Resolution and money
// rules live in service.GiftCredits (D1, D4); a failed batch — including
// unknown recipients — is translated to a client error (D3), never a
// panic or a naked 500.
func (h *Handlers) gift(w http.ResponseWriter, r *http.Request) {
	var req giftReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, "bad json")
		return
	}
	if len(req.Recipients) == 0 {
		writeErr(w, http.StatusBadRequest, "recipients required")
		return
	}
	lines := make([]service.GiftLine, len(req.Recipients))
	for i, rc := range req.Recipients {
		lines[i] = service.GiftLine{Email: rc.Email, Dollars: rc.Dollars}
	}
