// RegisterUser enforces unique, normalized emails (D5).
func (s *Shop) RegisterUser(email string) (*model.User, error) {
	norm := NormalizeEmail(email)
	if norm == "" {
		return nil, fmt.Errorf("register: empty email")
	}
	existing, err := s.store.GetByEmail(norm)
	if err == nil && existing != nil {
		return nil, fmt.Errorf("register %q: %w", email, ErrEmailTaken)
	}
	s.nextID++
	u := &model.User{ID: fmt.Sprintf("u%d", s.nextID), Email: norm}
	if err := s.store.SaveUser(u); err != nil {
		return nil, fmt.Errorf("register %q: %w", email, err)
	}
	return u, nil
}

// CreditCents applies money to a user's balance. Cents only (D2); errors
// are wrapped with %w so callers can match store.ErrNotFound (D3).
func (s *Shop) CreditCents(userID string, cents int) error {
	if cents <= 0 {
		return fmt.Errorf("credit %q: cents must be positive", userID)
	}
	u, err := s.store.GetUser(userID)
	if err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	u.CreditCents += cents
	if err := s.store.SaveUser(u); err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	return nil
}

// LookupByEmail resolves a user or returns the wrapped sentinel (D3).
func (s *Shop) LookupByEmail(email string) (*model.User, error) {
	u, err := s.store.GetByEmail(NormalizeEmail(email))
	if err != nil {
		return nil, fmt.Errorf("lookup %q: %w", email, err)
	}
	return u, nil
}

// GiftLine is one recipient entry of a batch gift (GIFT-101). Dollars
// cross into cents only inside Shop.GiftCredits via the sanctioned
// boundary (D2).
type GiftLine struct {
	Email   string
	Dollars float64
}

// GiftCredit reports one successfully credited recipient.
type GiftCredit struct {
	Email string `json:"email"`
	Cents int    `json:"cents"`
}

// GiftCredits credits every recipient by their dollar amount in one
// all-or-nothing batch (GIFT-101). Recipients are resolved by normalized
// email first (D5); an unknown address surfaces as wrapped
// store.ErrNotFound (D3) before any money moves, so callers answer with
// a client error instead of a panic or a naked 500.
func (s *Shop) GiftCredits(lines []GiftLine) ([]GiftCredit, error) {
	type resolved struct {
		userID string
		email  string
		cents  int
	}
	batch := make([]resolved, 0, len(lines))
	for _, l := range lines {
		u, err := s.LookupByEmail(l.Email)
		if err != nil {
			return nil, fmt.Errorf("gift %q: %w", l.Email, err)
		}
		cents := ParseDollarsToCents(l.Dollars)
		if cents <= 0 {
			return nil, fmt.Errorf("gift %q: dollars must be positive", l.Email)
		}
		batch = append(batch, resolved{userID: u.ID, email: u.Email, cents: cents})
	}
	credits := make([]GiftCredit, 0, len(batch))
	for _, b := range batch {
		if err := s.CreditCents(b.userID, b.cents); err != nil {
			return nil, fmt.Errorf("gift %q: %w", b.email, err)
		}
		credits = append(credits, GiftCredit{Email: b.email, Cents: b.cents})
	}
	return credits, nil
}

// ParseDollarsToCents is THE sanctioned dollar->cents boundary (D2). It
// rounds; naive int() truncation loses a cent on most real amounts.
func ParseDollarsToCents(dollars float64) int {
	return int(math.Round(dollars * 100))
}

func NormalizeEmail(e string) string {
	return strings.ToLower(strings.TrimSpace(e))
}

