package service

import (
	"errors"
	"fmt"
	"math"
	"strings"

	"giftshop/internal/model"
	"giftshop/internal/store"
)

// Shop is the business-logic layer (D1: the only caller of store;
// D4: every operation is a method on Shop).
type Shop struct {
	store  *store.MemoryStore
	nextID int
}

func New(s *store.MemoryStore) *Shop { return &Shop{store: s} }

// ErrEmailTaken reports a duplicate registration (D5).
var ErrEmailTaken = fmt.Errorf("email already registered")

// RegisterUser enforces unique, normalized emails (D5).
func (s *Shop) RegisterUser(email string) (*model.User, error) {
	norm := NormalizeEmail(email)
	if norm == "" {
		return nil, fmt.Errorf("register: empty email")
	}
	existing, err := s.store.GetByEmail(norm)
	if err == nil && existing != nil {
		return nil, fmt.Errorf("register %q: %w", email, ErrEmailTaken)
	}
	s.nextID++
	u := &model.User{ID: fmt.Sprintf("u%d", s.nextID), Email: norm}
	if err := s.store.SaveUser(u); err != nil {
		return nil, fmt.Errorf("register %q: %w", email, err)
	}
	return u, nil
}

// CreditCents applies money to a user's balance. Cents only (D2); errors
// are wrapped with %w so callers can match store.ErrNotFound (D3).
func (s *Shop) CreditCents(userID string, cents int) error {
	if cents <= 0 {
		return fmt.Errorf("credit %q: cents must be positive", userID)
	}
	u, err := s.store.GetUser(userID)
	if err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	u.CreditCents += cents
	if err := s.store.SaveUser(u); err != nil {
		return fmt.Errorf("credit %q: %w", userID, err)
	}
	return nil
}

// LookupByEmail resolves a user or returns the wrapped sentinel (D3).
func (s *Shop) LookupByEmail(email string) (*model.User, error) {
	u, err := s.store.GetByEmail(NormalizeEmail(email))
	if err != nil {
		return nil, fmt.Errorf("lookup %q: %w", email, err)
	}
	return u, nil
}

// ParseDollarsToCents is THE sanctioned dollar->cents boundary (D2). It
// rounds; naive int() truncation loses a cent on most real amounts.
func ParseDollarsToCents(dollars float64) int {
	return int(math.Round(dollars * 100))
}

func NormalizeEmail(e string) string {
	return strings.ToLower(strings.TrimSpace(e))
}

// Recipient is one line of a gift request: an outside-world dollar
// amount plus a target email (normalized before any comparison, D5).
type Recipient struct {
	Email   string  `json:"email"`
	Dollars float64 `json:"dollars"`
}

// GiftCredit reports one successfully applied credit. All amounts are
// integer cents (D2).
type GiftCredit struct {
	Email        string `json:"email"`
	AmountCents  int    `json:"amount_cents"`
	BalanceCents int    `json:"balance_cents"`
}

// GiftResult is the outcome of a batch gift. Unknown emails are
// reported, not fatal (D3): they are client data problems.
type GiftResult struct {
	Credited []GiftCredit `json:"credited,omitempty"`
	Unknown  []string     `json:"unknown,omitempty"`
}

// Gift credits each recipient's account by their dollar amount.
// Dollars cross into cents ONLY via ParseDollarsToCents (D2); unknown
// recipients are collected in the result instead of failing the batch
// (D3); the operation lives on Shop (D4).
func (s *Shop) Gift(recipients []Recipient) (*GiftResult, error) {
	res := &GiftResult{}
	for _, rcpt := range recipients {
		if math.IsNaN(rcpt.Dollars) || math.IsInf(rcpt.Dollars, 0) || rcpt.Dollars <= 0 {
			return nil, fmt.Errorf("gift %q: dollars must be positive", rcpt.Email)
		}
		cents := ParseDollarsToCents(rcpt.Dollars)
		u, err := s.LookupByEmail(rcpt.Email)
		if err != nil {
			if errors.Is(err, store.ErrNotFound) {
				res.Unknown = append(res.Unknown, NormalizeEmail(rcpt.Email))
				continue
			}
			return nil, fmt.Errorf("gift %q: %w", rcpt.Email, err)
		}
		if err := s.CreditCents(u.ID, cents); err != nil {
			return nil, fmt.Errorf("gift %q: %w", rcpt.Email, err)
		}
		fresh, err := s.store.GetUser(u.ID)
		if err != nil {
			return nil, fmt.Errorf("gift %q: %w", rcpt.Email, err)
		}
		res.Credited = append(res.Credited, GiftCredit{
			Email:        fresh.Email,
			AmountCents:  cents,
			BalanceCents: fresh.CreditCents,
		})
	}
	return res, nil
}

